    /// <summary>
    /// Execute and manage the filter pane and quick filter control queries.
    /// </summary>
    protected void datasourceApplyFilter()
    {
        QueryBuildDataSource qbdsOrderExtractScreen = SalesTable_ds.query().dataSourceTable(tableNum(SalesTable));

        qbdsOrderExtractScreen.clearRange(fieldNum(SalesTable, InventSiteId));
        qbdsOrderExtractScreen.clearRange(fieldNum(SalesTable, InventLocationId));
        qbdsOrderExtractScreen.clearRange(fieldNum(SalesTable, ShippingDateConfirmed));
        qbdsOrderExtractScreen.clearRange(fieldNum(SalesTable, METRoute));

        if(filterSite.text())
        {
            QueryBuildRange siteRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, InventSiteId));
            siteRange.value(filterSite.text());
        }

        if(filterInventLocationId.text())
        {
            QueryBuildRange inventLocationIdRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, InventLocationId));
            inventLocationIdRange.value(filterInventLocationId.text());
        }

        if(filterSalesShippingDateConfirmed.dateValue() != dateNull())
        {
            QueryBuildRange salesShippingDateConfirmedRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, ShippingDateConfirmed));
            salesShippingDateConfirmedRange.value(queryValue(filterSalesShippingDateConfirmed.dateValue()));
        }

        if(filterMETRoute.text())
        {
            QueryBuildRange routeRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, METRoute));
            routeRange.value(filterMETRoute.text());
        }

        SalesTable_ds.executeQuery();
    }

    /// <summary>
    /// Init method of form
    /// </summary>
    public void init()
    {
        super();

        OrderExtractGrid.footerShown(true);
    }

        /// <summary>
        /// set only sales orders which are confirmed or above status
        /// </summary>
        public void init()
        {
            super();

            QueryBuildDataSource qbdsOrderExtrect = SalesTable_ds.query().dataSourceTable(tableNum(SalesTable));
            QueryBuildRange SalesStatusRange = SysQuery::findOrCreateRange(qbdsOrderExtrect, fieldNum(SalesTable, SalesStatus));
            SalesStatusRange.value(queryValue(SalesStatus::Backorder));
            QueryBuildRange documentStatusRange = SysQuery::findOrCreateRange(qbdsOrderExtrect, fieldNum(SalesTable, DocumentStatus));
            documentStatusRange.value(queryValue(DocumentStatus::Confirmation));
        }

        /// <summary>
        /// To get grossWeight for the SalesLine Item.
        /// </summary>
        /// <param name = "_salesTable">passing the salesTable</param>
        /// <returns>gross weight</returns>
        [SysClientCacheDataMethodAttribute(true)]
        public  display ItemGrossWeight displayGrossWeight(SalesTable _salesTable)
        {
            SalesLine                   salesLineloc    = SalesLine::find(_salesTable.SalesId);
            METWHSPhysDimUOMSite        metPhysDimUOMUpdate;
            ItemGrossWeight             grossWeight;

            if (_salesTable.InventSiteId)
            {
                select firstonly Weight from metPhysDimUOMUpdate
                where metPhysDimUOMUpdate.ItemId   == salesLineloc.ItemId &&
                      metPhysDimUOMUpdate.UOM      == salesLineloc.SalesUnit &&
                    metPhysDimUOMUpdate.SiteId   == _salesTable.InventSiteId;
                {
                    grossWeight =  metPhysDimUOMUpdate.Weight;
                }
            }
            if (!grossWeight)
            {
                grossWeight =  WHSPhysDimUOM::findByItemIdAndUnitOfMeasure(salesLineloc.ItemId,salesLineloc.SalesUnit).Weight;
                
                if (!grossWeight)
                {
                    grossWeight = InventTable::find(salesLineloc.ItemId).grossWeight();
                }
            }
            return grossWeight;
        }

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <param name = "_salesTable">passing the salesTable</param>
/// <returns>cases</returns>
[SysClientCacheDataMethodAttribute(true)]
public display int displayCases(SalesTable _salesTable)
{
    SalesLine salesLineloc = SalesLine::find(_salesTable.SalesId);
    return any2Int(roundUp(UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(salesLineloc.SalesUnit).RecId,UnitOfMeasure::findBySymbol(METConstants::unitcase).RecId,EcoResProduct::findByProductNumber(salesLineloc.ItemId).RecId).Factor,0));
}

        /// <summary>
        /// To get unitVolume for the SalesLine Item.
        /// </summary>
        /// <param name = "_salesTable">passing the salesTable</param>
        /// <returns>unit volume</returns>
        [SysClientCacheDataMethodAttribute(true)]
        public display ItemVolume displayUnitVolume(SalesTable _salesTable)
        {
            METWHSPhysDimUOMSite        metPhysDimUOMUpdate;
            WHSPhysDimUOM               whsPhyDimUOM;
            ItemVolume                  volume;

            SalesLine salesLineloc = SalesLine::find(_salesTable.SalesId);
            if (_salesTable.InventSiteId)
            {
                select firstonly Depth, Height, Width from metPhysDimUOMUpdate
                where metPhysDimUOMUpdate.ItemId   == salesLineloc.ItemId &&
                      metPhysDimUOMUpdate.UOM      == salesLineloc.SalesUnit &&
                    metPhysDimUOMUpdate.SiteId   == _salesTable.InventSiteId;
                {
                    volume =  metPhysDimUOMUpdate.displayVolume();
                }
            }
            if (!volume)
            {
                whsPhyDimUOM =  WHSPhysDimUOM::findByItemIdAndUnitOfMeasure(salesLineloc.ItemId,salesLineloc.SalesUnit);
                if (whsPhyDimUOM.displayVolume())
                {
                    volume =  whsPhyDimUOM.displayVolume();
                }
                if (!volume)
                {
                    volume = InventTable::find(salesLineloc.ItemId).UnitVolume;
                }
            }
            return volume;
        }

        /// <summary>
        /// To get unitVolume for the SalesLine Item.
        /// </summary>
        /// <param name = "_salesTable">passing the salesTable</param>
        /// <returns>pallet volume</returns>
        [SysClientCacheDataMethodAttribute(true)]
        public display int displayPalletVolume(SalesTable _salesTable)
        {
            InventTable inventTable;
            SalesLine   salesLineloc;
            int         volume;
            SalesId     salesId;

            while select UnitVolume, ItemId from inventTable
                join salesLineloc
                    where salesLineloc.ItemId == inventTable.ItemId
                join salesId from _salesTable
                    where _salesTable.SalesId == salesLineloc.SalesId
                        && _salesTable.SalesStatus == SalesStatus::Backorder
                        && _salesTable.DocumentStatus == DocumentStatus::Confirmation
            {
                if (salesId != _salesTable.SalesId)
                {
                    volume += any2Int(inventTable.UnitVolume);
                    salesId =  _salesTable.SalesId;
                }
            }
            if (WHSParameters::find().METPalletVolume > 0)
            {
                return any2Int((volume/WHSParameters::find().METPalletVolume));
            }
            return 0;
        }

/// <summary>
/// calling the shown total value for cases, weight and volume
/// </summary>
/// <returns>total value</returns>
public int active()
{
    int ret;

    ret = super();
    METCases.totalShown(true);
    METWeight.totalShown(true);
    METVolume.totalShown(true);
    return ret;
}

        /// <summary>
        /// update the shippingdateconfirmed on relevent SalesLine.
        /// </summary>
        public void write()
        {
            SalesTable      salesTableOrig = SalesTable.orig();

            super();
            
            if (salesTableOrig.ShippingDateConfirmed != SalesTable.ShippingDateConfirmed)
            {
                update_recordset salesLine
                        setting ShippingDateConfirmed = SalesTable.ShippingDateConfirmed
                            where salesLine.SalesId == salesTable.SalesId;
            }
        }

